import {icon} from './icons.js';
import {createAgency} from './agency.js';
import {createExtension} from './addons.js';
import {STORAGE_KEY, ME, setCurrentUser, escapeHTML as e, uid, localDay, dueLabel, isOverdue, transitionTask, searchRecords, validateState, seed, templates} from './data.js';

const $ = (s,root=document)=>root.querySelector(s);
const app=$('#app'),overlay=$('#overlay-root');
let state=seed();
let cloud={preview:true,workspaceId:null,revision:0,user:{id:'roman',name:'Роман Шарычев',email:'',role:'preview'},members:[],workspaces:[],pending:null,busy:false,conflict:false,status:'Загрузка…',ready:false};
for(const key of ['boards','databases','folders','links','projects','reviews'])state[key]??=[];
let route=location.hash.slice(1)||'home', taskScope='mine',taskView='board',taskSpace='all',pageTab='recent',teamFilter='all',editing=false,modalReturn=null,searchIndex=-1;
const statuses={todo:'К выполнению',progress:'В работе',done:'Готово'};
const people=id=>state.people.find(p=>p.id===id)||state.people[0];
const space=id=>state.spaces.find(s=>s.id===id)||state.spaces[0];
const page=id=>state.pages.find(p=>p.id===id);
const shortName=p=>p.name.split(' ')[0];
const initials=p=>p.name.split(' ').slice(0,2).map(n=>n[0]).join('');
const avatar=(id,size='',title=true)=>{const p=people(id);return `<span class="avatar ${p.color} ${size}" ${title?`title="${e(p.name)}"`:''}>${e(initials(p))}</span>`;};
const dateLabel=v=>new Date(v).toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
const ago=v=>{const mins=Math.max(0,Math.floor((Date.now()-new Date(v))/60000));return mins<1?'Только что':mins<60?`${mins} мин назад`:mins<1440?`${Math.floor(mins/60)} ч назад`:dateLabel(v);};
const pill=(text,color='neutral')=>`<span class="pill ${color}">${e(text)}</span>`;
const pageStatus=p=>pill(p.status==='review'?'Нужна проверка':p.status==='draft'?'Черновик':'Актуально',p.status==='review'?'orange':p.status==='draft'?'neutral':'green');
const spaceIcon=s=>`<span class="space-icon ${s.color}">${icon(s.icon)}</span>`;
const empty=(title,text,action='')=>`<div class="empty-state"><span class="empty-icon">${icon('book')}</span><h3>${e(title)}</h3><p>${e(text)}</p>${action}</div>`;
function toast(text){const node=document.createElement('div');node.className='toast';node.innerHTML=icon('check')+`<span>${e(text)}</span>`;$('#toast-root').append(node);setTimeout(()=>node.remove(),4000);}
function publicState(source=state){const data=structuredClone(source);delete data.favorites;delete data.dismissedWelcome;delete data.notificationsRead;delete data.theme;return data;}
function syncLabel(){return cloud.preview?'Демо · без сохранения':cloud.status;}
function updateSync(){const el=document.getElementById('sync-status');if(el)el.textContent=syncLabel();document.body.classList.toggle('sync-failed',cloud.conflict);}
async function api(path,options={}){if(typeof agency!=='undefined'&&agency.isDemo())throw new Error('Это деморежим. Создайте своё пространство для работы с участниками и файлами.');const opts={credentials:'same-origin',...options,headers:{...options.headers}};if(options.body&&!(options.body instanceof FormData)){opts.body=JSON.stringify(options.body);opts.headers['Content-Type']='application/json';}const r=await fetch('/api/'+path,opts);let data;try{data=await r.json();}catch{throw new Error('Сервер временно недоступен');}if(!r.ok){const err=new Error(data.error||'Ошибка запроса');err.status=r.status;err.data=data;throw err;}return data;}
function preferences(){return {favorites:state.favorites||[],dismissedWelcome:Boolean(state.dismissedWelcome),notificationsRead:Boolean(state.notificationsRead)};}
function save(){if(cloud.preview){cloud.status='Изменения только в ознакомительном режиме';updateSync();return;}if(cloud.user.role==='viewer'){toast('У вас доступ только для просмотра');refreshCloud();return;}cloud.pending={state:publicState(),preferences:preferences()};cloud.status='Сохраняем…';updateSync();flush();}
async function flush(){if(cloud.busy||cloud.conflict||!cloud.pending)return;cloud.busy=true;const snapshot=cloud.pending;cloud.pending=null;try{const r=await api('workspace',{method:'PUT',body:{workspaceId:cloud.workspaceId,revision:cloud.revision,state:snapshot.state}});cloud.revision=r.revision;await api('preferences',{method:'PUT',body:{workspaceId:cloud.workspaceId,preferences:snapshot.preferences}});cloud.status='Все изменения сохранены';}catch(err){cloud.pending=cloud.pending||snapshot;cloud.conflict=true;cloud.status=err.status===409?'Конфликт изменений':'Не сохранено';toast(err.message);showSyncRecovery();}finally{cloud.busy=false;updateSync();if(cloud.pending&&!cloud.conflict)flush();}}
function showSyncRecovery(){let el=document.getElementById('sync-recovery');if(el)return;el=document.createElement('div');el.id='sync-recovery';el.className='sync-recovery';el.innerHTML='<span>Не удалось сохранить изменения. Сначала сохраните вашу копию.</span><button id="recover-export">Экспорт JSON</button><button id="recover-reload">Загрузить с сервера</button><button id="recover-retry">Повторить</button>';document.body.append(el);$('#recover-export').onclick=download;$('#recover-reload').onclick=()=>{if(!confirm('Загрузить серверную версию? Несохранённые изменения будут заменены.'))return;cloud.pending=null;cloud.conflict=false;el.remove();editing=false;refreshCloud(true);};$('#recover-retry').onclick=()=>{cloud.conflict=false;el.remove();flush();};}
async function refreshCloud(force=false){if(cloud.preview||cloud.busy||cloud.pending||(!force&&(editing||overlay.firstChild)))return;try{const data=await api('bootstrap?workspace='+encodeURIComponent(cloud.workspaceId));cloud.members=data.members;cloud.workspaces=data.workspaces;cloud.user=data.user;if(data.revision!==cloud.revision||force){const prefs=preferences();state={...data.state,...prefs};for(const key of ['boards','databases','folders','links','projects','reviews'])state[key]??=[];cloud.revision=data.revision;render();}}catch(err){if(force)toast(err.message);}}
async function switchWorkspace(id){if(editing&&!confirm('Выйти без сохранения?'))return;if(cloud.busy||cloud.pending)return toast('Дождитесь сохранения текущего пространства');closeModal();editing=false;cloud.conflict=false;await boot(id);route='home';history.replaceState(null,'','#home');render();}
async function boot(wid){try{const invite=new URLSearchParams(location.search).get('invite');if(invite){const result=await api('join',{method:'POST',body:{token:invite}});wid=result.workspaceId;history.replaceState(null,'',location.pathname+location.hash);}const data=await api('bootstrap'+(wid?'?workspace='+encodeURIComponent(wid):''));cloud={...cloud,preview:false,workspaceId:data.workspaceId,revision:data.revision,user:data.user,members:data.members,workspaces:data.workspaces,status:'Все изменения сохранены',ready:true};setCurrentUser(data.user.id);state={...data.state,favorites:data.preferences.favorites||[data.state.pages[0]?.id].filter(Boolean),dismissedWelcome:Boolean(data.preferences.dismissedWelcome),notificationsRead:Boolean(data.preferences.notificationsRead)};for(const key of ['boards','databases','folders','links','projects','reviews'])state[key]??=[];render();}catch(err){cloud.ready=true;cloud.status=err.status===401?'Войдите для сохранения':'Сервер недоступен';agency.start();if(err.status!==401)toast(err.message);}}
function importLegacy(){let old;try{old=JSON.parse(localStorage.getItem(STORAGE_KEY));}catch{}if(!old)return toast('В этом браузере нет данных первой версии');if(!confirm('Заменить содержимое пространства данными первой версии? Сначала экспортируйте текущую версию.'))return;const mine=people(ME);old.people=old.people.map(p=>p.id==='roman'?{...p,id:ME,name:mine.name,email:mine.email}:p);old.pages.forEach(p=>{if(p.owner==='roman')p.owner=ME;p.comments.forEach(c=>{if(c.author==='roman')c.author=ME;});});old.tasks.forEach(t=>{if(t.assignee==='roman')t.assignee=ME;});old.activity.forEach(a=>{if(a.person==='roman')a.person=ME;});for(const key of ['boards','databases','folders','links','projects','reviews'])old[key]??=[];state=old;save();render();toast('Данные перенесены');}

function activity(text,pageId){state.activity.unshift({id:uid('a'),person:ME,text,page:pageId||null,at:new Date().toISOString()});state.activity=state.activity.slice(0,80);state.notificationsRead=false;}
function sanitize(html){
  const doc=new DOMParser().parseFromString(String(html),'text/html');
  const allowed=new Set(['P','H2','H3','H4','STRONG','B','EM','I','U','S','UL','OL','LI','BLOCKQUOTE','TABLE','THEAD','TBODY','TR','TH','TD','BR','HR','A','CODE','PRE','DIV','SPAN']);
  for(const el of [...doc.body.querySelectorAll('*')]){
    if(['SCRIPT','STYLE','IFRAME','OBJECT','SVG','MATH','FORM','INPUT','BUTTON','IMG','LINK','META'].includes(el.tagName)){el.remove();continue;}
    if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);continue;}
    const href=el.getAttribute('href');for(const a of [...el.attributes])el.removeAttribute(a.name);
    if(el.tagName==='A'&&href&&/^(https?:\/\/|mailto:|#)/i.test(href)){el.setAttribute('href',href);el.setAttribute('rel','noopener noreferrer');}
  }
  return doc.body.innerHTML;
}
function go(next){if(editing&&!confirm('Выйти без сохранения изменений?'))return;editing=false;closeModal();if(next!==route)history.pushState(null,'',`#${next}`);route=next;render();window.scrollTo(0,0);}
function titleForRoute(){const at=agency.title();if(at)return at;const extended=ext.title();if(extended)return extended;if(route==='home')return 'Обзор';if(route.startsWith('page/'))return page(route.split('/')[1])?.title||'Страница';if(route.startsWith('space/'))return space(route.split('/')[1]).name;return {knowledge:'База знаний',spaces:'Пространства',tasks:'Задачи',team:'Команда',templates:'Шаблоны',favorites:'Избранное',settings:'Настройки'}[route]||'Обзор';}
function navItem(id,label,name,count=''){const selected=route===id||(id==='knowledge'&&route.startsWith('page/'));return `<button class="nav-item ${selected?'active':''}" data-nav="${id}" ${selected?'aria-current="page"':''}>${icon(name)}<span>${label}</span>${count!==''?`<span class="nav-count">${count}</span>`:''}</button>`;}
function render(){
  if(agency.gate())return;
  document.title=`${titleForRoute()} · Apollo Task`;
  const mine=state.tasks.filter(t=>t.assignee===ME&&t.status!=='done').length;
  app.innerHTML=`<header class="topbar"><div class="topbar-brand"><button class="icon-btn mobile-menu" data-action="mobile-menu" aria-label="Открыть навигацию">${icon('menu')}</button><a class="brand" href="#home"><img src="./apollo-symbol.svg" alt="" width="31" height="31"><span>Apollo<span class="brand-task"> Task</span></span></a><span class="top-divider"></span><span class="workspace-top">COMPANY WORKSPACE</span></div><button class="global-search" data-action="search" aria-label="Поиск по пространству">${icon('search')}<span>Поиск по Apollo Task</span><kbd>Ctrl K</kbd></button><div class="top-actions"><button class="btn primary create-btn" data-action="create">${icon('plus')}<span>Создать</span>${icon('down')}</button><span class="top-divider"></span><button class="icon-btn notification-btn ${state.notificationsRead?'':'has-dot'}" data-action="notifications" aria-label="Открыть уведомления">${icon('bell')}</button><button class="icon-btn help-top" data-action="help" aria-label="Помощь">${icon('help')}</button><button class="avatar-button" data-action="profile" aria-label="Мой профиль">${avatar(ME)}</button></div></header>
  <div class="sidebar-shade" data-action="mobile-menu"></div><aside class="sidebar"><button class="workspace-switch" data-nav="settings"><span class="workspace-avatar">A</span><span><strong>${e(state.workspace)}</strong><small>${cloud.preview?state.people.length:cloud.members.length||1} ${plural(cloud.preview?state.people.length:cloud.members.length||1,'участник','участника','участников')}</small></span>${icon('down')}</button><nav aria-label="Основная навигация">${navItem('home','Обзор','home')}${navItem('library','Всё содержимое','grid')}${navItem('knowledge','База знаний','book')}${navItem('tasks','Задачи','task',mine)}${navItem('team','Команда','users')}${navItem('profile','Мой кабинет','briefcase')}${navItem('drafts','Черновики','edit')}</nav><div class="sidebar-section-title"><span>ПРОСТРАНСТВА</span><button class="icon-btn tiny" data-action="new-space" aria-label="Создать пространство">${icon('plus')}</button></div><nav aria-label="Пространства">${state.spaces.map(s=>`<button class="nav-item space-nav ${route===`space/${s.id}`?'active':''}" data-nav="space/${e(s.id)}"><span class="nav-space-dot ${s.color}">${icon(s.icon)}</span><span>${e(s.name)}</span></button>`).join('')}</nav>${ext.sidebar()}<div class="sidebar-section-title"><span>ИЗБРАННОЕ</span><button class="icon-btn tiny" data-nav="favorites" aria-label="Открыть избранное">${icon('star')}</button></div><nav class="favorite-nav" aria-label="Избранные страницы">${state.pages.filter(p=>state.favorites?.includes(p.id)).slice(0,4).map(p=>`<button class="nav-item ${route===`page/${p.id}`?'active':''}" data-nav="page/${e(p.id)}">${icon(p.icon)}<span>${e(p.title)}</span></button>`).join('')||'<span class="sidebar-hint">Добавляйте важные страницы ★</span>'}</nav><button class="nav-item templates-nav ${route==='templates'?'active':''}" data-nav="templates">${icon('template')}<span>Шаблоны</span></button><div class="sidebar-bottom"><div class="local-notice"><span class="status-dot"></span><span id="sync-status">${e(syncLabel())}</span><button data-action="help" aria-label="О сервисе">${icon('info')}</button></div><button class="nav-item ${route==='settings'?'active':''}" data-nav="settings">${icon('settings')}<span>Настройки</span></button></div></aside>
  ${cloud.preview?'<div class="preview-notice"><span>Ознакомительный режим. Для серверного сохранения войдите в аккаунт.</span><a href="/signin-with-chatgpt?return_to=%2F" target="_top">Войти через ChatGPT →</a></div>':''}<main id="main" class="main ${route.startsWith('page/')?'document-main':''}" tabindex="-1"><div class="page-content">${content()}</div><footer class="main-footer"><span>Apollo Task</span><span>Меньше поисков. Больше ясности.</span><button data-action="help">Помощь ${icon('arrow')}</button></footer></main>`;
  bind();
  ext.enhancePage();
  agency.enhance();
  updateSync();
  if(cloud.user.role==='viewer'){for(const el of app.querySelectorAll('[data-action=\"create\"],[data-action=\"new-page\"],[data-action=\"new-task\"],[data-action=\"new-person\"],[data-action=\"new-space\"],[data-action=\"edit-page\"],[data-db-row],[data-db-column],[data-board-add],[data-board-connect],[data-delete-item],[data-move-item],[data-complete],[data-quick-create],[data-use-template],[data-agency="new-project"],[data-edit-project],[data-project-page],[data-project-task],[data-ext-action=\"create\"]')){el.disabled=true;el.title='Доступ только для просмотра';}}
}
function plural(n,one,few,many){return n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many;}
function breadcrumb(last=''){return `<div class="breadcrumb"><button data-nav="home" aria-label="На главную">${icon('home')}</button>${icon('chevron')}<span>${e(last||titleForRoute())}</span></div>`;}
function heading(title,sub,button=''){return `${breadcrumb()}<div class="page-heading"><div><h1>${e(title)}</h1><p>${e(sub)}</p></div>${button}</div>`;}
function content(){
  const agencyView=agency.view();if(agencyView!==null)return agencyView;
  const additional=ext.view();if(additional!==null)return additional;
  if(route==='home')return agency.home();
  if(route==='knowledge'||route==='favorites')return knowledge();
  if(route==='spaces')return spacesView();
  if(route.startsWith('space/'))return spaceView(route.split('/')[1]);
  if(route.startsWith('page/'))return documentView(route.split('/')[1]);
  if(route==='tasks')return tasksView();
  if(route==='team')return teamView();
  if(route==='templates')return templatesView();
  if(route==='settings')return settingsView();
  return empty('Страница не найдена','Вернитесь в рабочее пространство.',`<button class="btn primary" data-nav="home">На главную</button>`);
}
function home(){const mine=state.tasks.filter(t=>t.assignee===ME&&t.status!=='done');return `<div class="welcome-row"><span>Ваше рабочее пространство</span><span class="today-label">${new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}</span></div><div class="home-heading"><div><h1>С возвращением, ${e(shortName(people(ME)))} <span class="wave">✦</span></h1><p>Знания, задачи и команда — всё на своих местах.</p></div><button class="btn secondary" data-action="new-page">${icon('plus')}Новая страница</button></div>
  ${!state.dismissedWelcome?`<section class="intro-banner"><div class="intro-copy"><span class="eyebrow">APOLLO TASK / CREATE TOGETHER</span><h2>Идеи в фокусе.<br>Команда в движении.</h2><p>Сохраняйте знания, делитесь идеями<br class="desktop-break"> и превращайте договорённости в результат.</p><button class="btn banner-btn" data-nav="page/welcome">Заглянуть в базу знаний ${icon('arrow')}</button></div><div class="banner-art" aria-hidden="true"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="art-spark">✦</div><div class="floating-note note-back"><span class="mini-icon">${icon('users')}</span><i></i><i></i></div><div class="floating-note note-front"><span class="note-title"><b class="mini-logo">A</b> План на отличный результат</span><span class="art-line wide"></span><span class="art-line"></span><span class="art-task"><b>${icon('check')}</b><i></i></span><span class="art-task"><b>${icon('check')}</b><i></i></span><span class="art-task last"><b></b><i></i></span><div class="art-avatars"><span>РШ</span><span>АС</span><span>МВ</span><small>Вместе проще</small></div></div><div class="floating-label">${icon('check')} Всё связано</div><div class="small-spark">✧</div></div><button class="icon-btn dismiss-banner" data-action="dismiss-banner" aria-label="Скрыть приветственный блок">${icon('close')}</button></section>`:''}
  ${ext.homeExtra()}<section class="spaces-section"><div class="section-heading"><h2>Пространства команды <span class="count-light">${state.spaces.length}</span></h2><button class="text-link" data-nav="spaces">Все пространства ${icon('arrow')}</button></div><div class="space-grid">${state.spaces.slice(0,4).map(spaceCard).join('')}</div></section>
  <div class="home-columns"><div><section class="recent-section"><div class="section-heading"><h2>Продолжить работу</h2><button class="text-link" data-nav="knowledge">Все страницы ${icon('arrow')}</button></div><div class="tabs"><button class="${pageTab==='recent'?'active':''}" data-home-tab="recent">Недавние</button><button class="${pageTab==='favorites'?'active':''}" data-home-tab="favorites">Избранное</button><button class="${pageTab==='mine'?'active':''}" data-home-tab="mine">Мои страницы</button></div><div class="recent-list">${filteredPages(pageTab).slice(0,4).map(p=>pageRow(p)).join('')||empty('Здесь пока пусто','Создайте страницу или добавьте её в избранное.')}</div></section><section class="activity-section"><div class="section-heading"><h2>В команде</h2><span class="subtle">Последние обновления</span></div>${state.activity.slice(0,3).map(a=>`<div class="activity-row">${avatar(a.person,'small')}<div><p><strong>${e(shortName(people(a.person)))}</strong> ${e(a.text)}</p>${a.page&&page(a.page)?`<button data-nav="page/${e(a.page)}">${e(page(a.page).title)}</button>`:''}</div><span class="activity-time">${ago(a.at)}</span></div>`).join('')}</section></div><aside class="home-right"><section class="task-widget"><div class="section-heading"><h2>Мои задачи <span class="count-light">${mine.length}</span></h2><button class="icon-btn tiny" data-action="new-task" aria-label="Добавить задачу">${icon('plus')}</button></div><p class="widget-subtitle">Небольшие шаги к общему результату</p>${mine.slice(0,3).map(t=>`<div class="widget-task"><button class="round-check" data-complete="${e(t.id)}" aria-label="Завершить: ${e(t.title)}"></button><button class="task-widget-content" data-task="${e(t.id)}"><strong>${e(t.title)}</strong><span>${e(space(t.space).name)}<b class="${isOverdue(t)?'overdue':t.due===localDay()?'today':''}">${e(dueLabel(t.due))}</b></span></button></div>`).join('')||`<div class="all-done">${icon('check')} Все задачи выполнены</div>`}<button class="widget-footer" data-nav="tasks">Открыть мои задачи ${icon('arrow')}</button></section><section class="template-teaser"><span class="teaser-icon">${icon('template')}</span><h3>Хорошее начало —<br>готовый шаблон</h3><p>Встреча, проект или инструкция.<br>Структура уже под рукой.</p><button class="text-link" data-nav="templates">Выбрать шаблон ${icon('arrow')}</button></section></aside></div>`;}
function filteredPages(filter){return [...state.pages].filter(p=>filter==='favorites'?state.favorites?.includes(p.id):filter==='mine'?p.owner===ME:true).sort((a,b)=>new Date(b.updated)-new Date(a.updated));}
function spaceCard(s){const docs=state.pages.filter(p=>p.space===s.id),owners=[...new Set(docs.map(p=>p.owner))];return `<button class="space-card" data-nav="space/${e(s.id)}"><div class="space-card-top">${spaceIcon(s)}${icon('arrow','card-arrow')}</div><h3>${e(s.name)}</h3><p>${e(s.description)}</p><div class="space-card-footer"><span>${docs.length} ${plural(docs.length,'страница','страницы','страниц')}</span><span class="avatar-stack">${owners.slice(0,3).map(id=>avatar(id,'xs')).join('')}</span></div></button>`;}
function pageRow(p){return `<div class="page-row"><span class="page-type-icon ${space(p.space).color}">${icon(p.icon)}</span><button class="page-row-main" data-nav="page/${e(p.id)}"><strong>${e(p.title)}</strong><span>${e(space(p.space).name)} <b>·</b> ${e(shortName(people(p.owner)))} <b>·</b> ${ago(p.updated)}</span></button><button class="icon-btn favorite-button ${state.favorites?.includes(p.id)?'is-favorite':''}" data-favorite="${e(p.id)}" aria-label="${state.favorites?.includes(p.id)?'Убрать из избранного':'Добавить в избранное'}">${icon('star')}</button></div>`;}
function knowledge(){const favorites=route==='favorites';return `${heading(favorites?'Избранное':'База знаний',favorites?'Самое нужное — всегда под рукой.':'Общий контекст для всей команды. Сохраняйте то, что важно.',`<button class="btn primary" data-action="new-page">${icon('plus')}Создать страницу</button>`)}<div class="filter-bar"><div class="tabs"><button class="active" data-page-filter="all">${favorites?'Избранные страницы':'Все страницы'} <span>${favorites?filteredPages('favorites').length:state.pages.length}</span></button><button data-page-filter="mine">Мои страницы</button><button data-page-filter="review">Нужна проверка</button></div><div class="inline-search">${icon('search')}<input id="page-filter-input" aria-label="Найти страницу" placeholder="Найти страницу…"></div></div><div id="knowledge-results">${knowledgeTable(favorites?filteredPages('favorites'):filteredPages('recent'))}</div>`;}
function knowledgeTable(pages){return pages.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Название</th><th>Пространство</th><th>Ответственный</th><th>Обновлено</th><th>Статус</th><th></th></tr></thead><tbody>${pages.map(p=>`<tr><td><button class="table-page-title" data-nav="page/${e(p.id)}"><span class="page-type-icon ${space(p.space).color}">${icon(p.icon)}</span><span>${e(p.title)}<small>${e(p.excerpt||'Новая страница')}</small></span></button></td><td><span class="space-label"><i class="dot ${space(p.space).color}"></i>${e(space(p.space).name)}</span></td><td><span class="person-inline">${avatar(p.owner,'xs')}${e(shortName(people(p.owner)))}</span></td><td class="nowrap subtle">${ago(p.updated)}</td><td>${pageStatus(p)}</td><td><button class="icon-btn ${state.favorites?.includes(p.id)?'is-favorite':''}" data-favorite="${e(p.id)}" aria-label="Избранное: ${e(p.title)}">${icon('star')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Страниц пока нет','Создайте первую страницу или измените фильтр.',`<button class="btn primary" data-action="new-page">${icon('plus')}Создать страницу</button>`);}
function spacesView(){return `${heading('Пространства','Знания и работа, объединённые общей темой.',`<button class="btn primary" data-action="new-space">${icon('plus')}Новое пространство</button>`)}<div class="space-grid full-spaces">${state.spaces.map(spaceCard).join('')}</div>`;}
function spaceView(id){const s=state.spaces.find(s=>s.id===id);if(!s)return empty('Пространство не найдено','Откройте список пространств.');const docs=state.pages.filter(p=>p.space===id);return `${breadcrumb(s.name)}<div class="space-page-cover ${s.color}"><span class="space-cover-icon">${icon(s.icon)}</span><div><span class="eyebrow">ПРОСТРАНСТВО КОМАНДЫ</span><h1>${e(s.name)}</h1><p>${e(s.description)}</p></div><button class="btn secondary" data-action="new-page" data-space="${e(s.id)}">${icon('plus')}Добавить страницу</button></div><div class="section-heading space-list-heading"><h2>Страницы <span class="count-light">${docs.length}</span></h2><span class="subtle">Материалы доступны участникам пространства</span></div>${knowledgeTable(docs)}${ext.sectionExtra(id)}<div class="space-related"><h2>Задачи пространства</h2><div class="simple-task-list">${state.tasks.filter(t=>t.space===id).slice(0,5).map(taskListRow).join('')||'<p class="subtle">Задачи появятся здесь после создания.</p>'}</div><button class="text-link" data-action="space-tasks" data-space="${e(id)}">Все задачи пространства ${icon('arrow')}</button></div>`;}
function documentView(id){const p=page(id);if(!p)return empty('Страница не найдена','Возможно, она была удалена.',`<button class="btn secondary" data-nav="knowledge">В базу знаний</button>`);const s=space(p.space);return `<div class="document-top"><div class="breadcrumb"><button data-nav="knowledge">База знаний</button>${icon('chevron')}<button data-nav="space/${e(s.id)}">${e(s.name)}</button>${icon('chevron')}<span>Страница</span></div><div class="document-actions"><button class="icon-btn ${state.favorites?.includes(p.id)?'is-favorite':''}" data-favorite="${e(p.id)}" aria-label="В избранное">${icon('star')}</button><button class="btn ghost" data-action="history" data-id="${e(p.id)}">${icon('history')}<span>История</span></button><button class="btn secondary" data-action="share" data-id="${e(p.id)}">${icon('link')}<span>Ссылка</span></button><button class="btn primary" data-action="edit-page" data-id="${e(p.id)}">${icon('edit')}<span>Редактировать</span></button></div></div><div class="document-layout"><article class="document"><div class="document-icon ${s.color}">${icon(p.icon)}</div><h1>${e(p.title)}</h1><div class="document-meta">${avatar(p.owner,'small')}<span>${e(people(p.owner).name)}</span><span class="meta-dot">·</span><span>Обновлено ${ago(p.updated)}</span>${pageStatus(p)}</div><div class="document-body">${sanitize(p.content)}</div><section class="linked-tasks"><div class="section-heading"><h2>Связанные задачи</h2><button class="text-link" data-action="new-task" data-page="${e(p.id)}">${icon('plus')}Добавить</button></div>${state.tasks.filter(t=>t.page===p.id).map(taskListRow).join('')||'<p class="subtle">Превратите договорённость в конкретный следующий шаг.</p>'}</section><section class="comments"><h2>Обсуждение <span class="count-light">${p.comments.length}</span></h2>${p.comments.map(c=>`<div class="comment">${avatar(c.author,'small')}<div><div class="comment-meta"><strong>${e(people(c.author).name)}</strong><span>${ago(c.at)}</span></div><p>${e(c.text)}</p></div></div>`).join('')}<form id="comment-form" data-page="${e(p.id)}" class="comment-form">${avatar(ME,'small')}<div><textarea name="comment" required maxlength="3000" rows="3" placeholder="Задайте вопрос или поделитесь мыслью…" aria-label="Ваш комментарий"></textarea><div class="comment-form-footer"><span>Обсуждение доступно участникам пространства</span><button class="btn primary" type="submit">Отправить</button></div></div></form></section></article><aside class="document-aside"><div class="document-info"><span class="eyebrow">ОТВЕТСТВЕННЫЙ ЗА СТРАНИЦУ</span><button class="doc-owner" data-person="${e(p.owner)}">${avatar(p.owner)}<span><strong>${e(people(p.owner).name)}</strong><small>${e(people(p.owner).role)}</small></span></button></div><div class="toc"><span class="eyebrow">НА ЭТОЙ СТРАНИЦЕ</span>${toc(p.content)}</div><div class="document-context">${icon('info')}<p>Заметили неточность? Оставьте комментарий или обновите страницу.</p></div></aside></div>`;}
function toc(html){const doc=new DOMParser().parseFromString(sanitize(html),'text/html');return [...doc.querySelectorAll('h2,h3')].map((h,i)=>`<button data-toc="${i}">${e(h.textContent)}</button>`).join('');}
function taskListRow(t){return `<div class="simple-task"><button class="round-check ${t.status==='done'?'checked':''}" data-complete="${e(t.id)}" aria-label="${t.status==='done'?'Вернуть в работу':'Завершить'}: ${e(t.title)}">${t.status==='done'?icon('check'):''}</button><button class="simple-task-title ${t.status==='done'?'completed':''}" data-task="${e(t.id)}">${e(t.title)}</button>${pill(statuses[t.status],t.status==='done'?'green':t.status==='progress'?'blue':'neutral')}<span class="task-date ${isOverdue(t)?'overdue':''}">${e(dueLabel(t.due))}</span>${avatar(t.assignee,'xs')}</div>`;}
function tasksView(){const tasks=state.tasks.filter(t=>(taskScope==='mine'?t.assignee===ME:true)&&(taskSpace==='all'||t.space===taskSpace));return `${heading('Задачи','Понятный следующий шаг для каждого в команде.',`<button class="btn primary" data-action="new-task">${icon('plus')}Новая задача</button>`)}<div class="tasks-toolbar"><div class="tabs"><button class="${taskScope==='mine'?'active':''}" data-task-scope="mine">Мои задачи <span>${state.tasks.filter(t=>t.assignee===ME&&t.status!=='done').length}</span></button><button class="${taskScope==='all'?'active':''}" data-task-scope="all">Вся команда</button></div><div class="task-toolbar-right"><select id="task-space-filter" aria-label="Пространство задач"><option value="all">Все пространства</option>${state.spaces.map(s=>`<option value="${e(s.id)}" ${taskSpace===s.id?'selected':''}>${e(s.name)}</option>`).join('')}</select><div class="segmented"><button class="${taskView==='board'?'active':''}" data-task-view="board" aria-label="Доска">${icon('board')}</button><button class="${taskView==='list'?'active':''}" data-task-view="list" aria-label="Список">${icon('list')}</button></div></div></div>${taskView==='board'?`<div class="kanban">${Object.entries(statuses).map(([key,label])=>`<section class="kanban-column" data-drop-status="${key}"><div class="column-heading"><h2><i class="column-dot ${key}"></i>${label}<span>${tasks.filter(t=>t.status===key).length}</span></h2><button class="icon-btn tiny" data-action="new-task" data-status="${key}" aria-label="Добавить задачу в ${label}">${icon('plus')}</button></div><div class="kanban-cards">${tasks.filter(t=>t.status===key).map(taskCard).join('')||'<div class="column-empty">Здесь пока нет задач</div>'}</div><button class="add-card" data-action="new-task" data-status="${key}">${icon('plus')}Добавить задачу</button></section>`).join('')}</div><p class="board-hint">${icon('info')} Перетаскивайте задачи между колонками или меняйте статус в карточке.</p>`:`<div class="task-list-view">${tasks.map(taskListRow).join('')||empty('Задач пока нет','Добавьте первый шаг к вашему результату.')}</div>`}`;}
function taskCard(t){return `<article class="task-card" draggable="true" data-drag-task="${e(t.id)}"><div class="task-card-label">${pill(space(t.space).name,space(t.space).color)}<button class="icon-btn tiny" data-task="${e(t.id)}" aria-label="Открыть задачу">${icon('more')}</button></div><button class="task-card-title ${t.status==='done'?'completed':''}" data-task="${e(t.id)}">${e(t.title)}</button>${t.page&&page(t.page)?`<button class="task-card-page" data-nav="page/${e(t.page)}">${icon('file')}${e(page(t.page).title)}</button>`:''}<div class="task-card-bottom"><span class="task-date ${isOverdue(t)?'overdue':t.due===localDay()&&t.status!=='done'?'today':''}">${icon('clock')}${e(dueLabel(t.due))}</span><span class="priority ${t.priority}" title="${t.priority==='high'?'Высокий':t.priority==='low'?'Низкий':'Обычный'} приоритет"><i></i><i></i><i></i></span>${avatar(t.assignee,'small')}</div></article>`;}
function teamView(){const teams=[...new Set(state.people.map(p=>p.team))];return `${heading('Команда','Кто рядом, за что отвечает и с чем может помочь.',`<button class="btn primary" data-action="new-person">${icon('plus')}Добавить сотрудника</button>`)}<div class="team-banner"><span class="team-banner-icon">${icon('users')}</span><div><strong>За каждым результатом — люди</strong><p>У каждого своя зона ответственности. У команды — общий контекст.</p></div><div class="avatar-stack">${state.people.slice(0,5).map(p=>avatar(p.id)).join('')}</div></div><div class="filter-bar"><div class="tabs"><button class="${teamFilter==='all'?'active':''}" data-team-filter="all">Все сотрудники <span>${state.people.length}</span></button>${teams.map(t=>`<button class="${teamFilter===t?'active':''}" data-team-filter="${e(t)}">${e(t)}</button>`).join('')}</div></div><div class="team-grid">${state.people.filter(p=>teamFilter==='all'||p.team===teamFilter).map(p=>`<button class="person-card" data-person="${e(p.id)}">${avatar(p.id,'large')}<h3>${e(p.name)}${p.id===ME?'<span class="you-label">Вы</span>':''}</h3><span class="person-role">${e(p.role)}</span>${pill(p.team,p.color)}<div class="person-responsibility"><span>ЗОНА ОТВЕТСТВЕННОСТИ</span><p>${e(p.responsibility)}</p></div><div class="person-card-footer"><span>${state.tasks.filter(t=>t.assignee===p.id&&t.status!=='done').length} активных задач</span>${icon('arrow')}</div></button>`).join('')}</div>`;}
function templatesView(){return `${heading('Шаблоны','Начните с готовой структуры. Остальное — ваши идеи.')}<div class="template-feature"><span class="template-feature-icon">${icon('template')}</span><div><span class="eyebrow">МЕНЬШЕ РУТИНЫ, БОЛЬШЕ СМЫСЛА</span><h2>Чистый лист уже не такой чистый</h2><p>Проверенные структуры для повседневной работы небольшой команды.</p></div></div><div class="template-grid">${templates.map(t=>`<button class="template-card" data-template="${t.id}"><div class="template-preview ${t.color}"><div class="template-paper"><span>${icon(t.icon)}</span><i></i><b></b><i></i><i></i><b></b><i></i></div></div><div class="template-card-body"><h3>${e(t.title)}</h3><p>${e(t.description)}</p><span class="text-link">Использовать шаблон ${icon('arrow')}</span></div></button>`).join('')}</div>`;}
function settingsView(){return `${heading('Настройки','Ваше пространство и сохранённые данные.')}<div class="settings-layout"><section class="settings-card"><h2>Рабочее пространство</h2><p>Название увидят на главной странице и в навигации.</p><form id="workspace-form"><label class="field">Название<input name="workspace" value="${e(state.workspace)}" maxlength="60" required></label><button class="btn primary" type="submit">Сохранить</button></form></section><section class="settings-card"><h2>Данные пространства</h2><p>В этой версии страницы, задачи и комментарии сохраняются в текущем браузере. Экспортируйте файл, чтобы перенести их на другое устройство.</p><div class="settings-stats"><span><strong>${state.pages.length}</strong> страниц</span><span><strong>${state.tasks.length}</strong> задач</span><span><strong>${state.people.length}</strong> сотрудников</span></div><div class="button-row"><button class="btn secondary" data-action="export">${icon('download')}Экспорт JSON</button><label class="btn secondary import-label">${icon('upload')}Импорт данных<input type="file" id="import-file" accept="application/json,.json" hidden></label></div></section><section class="settings-card"><h2>О первой версии</h2><p>Apollo Task 0.1 — интерактивный MVP. Данные команды демонстрационные. Общий сервер, авторизация, приглашения и разграничение доступа появятся на следующем этапе.</p><p>Создание сотрудника добавляет карточку в текущий браузер и не отправляет приглашение.</p><button class="text-link" data-action="help">Как пользоваться ${icon('arrow')}</button></section><section class="settings-card danger-zone"><h2>Начать заново</h2><p>Заменить текущие данные первоначальным примером. Сначала сохраните экспорт, если хотите сохранить свою работу.</p><button class="btn danger" data-action="reset">Восстановить демо-данные</button></section></div>`;}

function bind(root=app){
  ext.bind(root);
  root.querySelectorAll('[data-nav]').forEach(n=>n.onclick=()=>{document.body.classList.remove('mobile-nav-open');go(n.dataset.nav);});
  root.querySelectorAll('[data-action]').forEach(n=>n.onclick=()=>action(n.dataset.action,n));
  root.querySelectorAll('[data-favorite]').forEach(n=>n.onclick=()=>{const id=n.dataset.favorite;state.favorites??=[];const added=!state.favorites.includes(id);state.favorites=added?[...state.favorites,id]:state.favorites.filter(x=>x!==id);save();render();toast(added?'Страница добавлена в избранное':'Страница убрана из избранного');});
  root.querySelectorAll('[data-home-tab]').forEach(n=>n.onclick=()=>{pageTab=n.dataset.homeTab;render();});
  root.querySelectorAll('[data-task-scope]').forEach(n=>n.onclick=()=>{taskScope=n.dataset.taskScope;render();});
  root.querySelectorAll('[data-task-view]').forEach(n=>n.onclick=()=>{taskView=n.dataset.taskView;render();});
  root.querySelectorAll('[data-team-filter]').forEach(n=>n.onclick=()=>{teamFilter=n.dataset.teamFilter;render();});
  root.querySelectorAll('[data-task]').forEach(n=>n.onclick=()=>taskModal(n.dataset.task));
  root.querySelectorAll('[data-person]').forEach(n=>n.onclick=()=>personModal(n.dataset.person));
  root.querySelectorAll('[data-template]').forEach(n=>n.onclick=()=>newPageModal(n.dataset.template));
  root.querySelectorAll('[data-complete]').forEach(n=>n.onclick=()=>{const t=state.tasks.find(t=>t.id===n.dataset.complete);state.tasks=transitionTask(state.tasks,t.id,t.status==='done'?'todo':'done');activity(t.status==='done'?'вернул задачу в работу':'завершил задачу',t.page);save();render();toast(t.status==='done'?'Задача возвращена в работу':'Задача выполнена. Отличная работа!');});
  root.querySelectorAll('[data-toc]').forEach(n=>n.onclick=()=>document.querySelectorAll('.document-body h2,.document-body h3')[+n.dataset.toc]?.scrollIntoView({behavior:'smooth',block:'start'}));
  root.querySelectorAll('[data-drag-task]').forEach(n=>{n.ondragstart=ev=>{ev.dataTransfer.setData('text/plain',n.dataset.dragTask);n.classList.add('dragging');};n.ondragend=()=>n.classList.remove('dragging');});
  root.querySelectorAll('[data-drop-status]').forEach(n=>{n.ondragover=ev=>{ev.preventDefault();n.classList.add('drag-over');};n.ondragleave=()=>n.classList.remove('drag-over');n.ondrop=ev=>{ev.preventDefault();const id=ev.dataTransfer.getData('text/plain');if(!state.tasks.some(t=>t.id===id))return;state.tasks=transitionTask(state.tasks,id,n.dataset.dropStatus);activity('изменил статус задачи',state.tasks.find(t=>t.id===id).page);save();render();toast('Статус задачи обновлён');};});
  $('#task-space-filter',root)?.addEventListener('change',ev=>{taskSpace=ev.target.value;render();});
  const input=$('#page-filter-input',root);if(input){let filter='all';const update=()=>{const q=input.value.trim().toLowerCase();const pages=filteredPages(route==='favorites'?'favorites':'recent').filter(p=>(filter==='mine'?p.owner===ME:filter==='review'?p.status==='review':true)&&`${p.title} ${p.excerpt}`.toLowerCase().includes(q));$('#knowledge-results').innerHTML=knowledgeTable(pages);bind($('#knowledge-results'));};input.oninput=update;root.querySelectorAll('[data-page-filter]').forEach(n=>n.onclick=()=>{filter=n.dataset.pageFilter;root.querySelectorAll('[data-page-filter]').forEach(b=>b.classList.toggle('active',b===n));update();});}
  $('#comment-form',root)?.addEventListener('submit',ev=>{ev.preventDefault();const form=ev.target,value=form.comment.value.trim();if(!value)return;const p=page(form.dataset.page);p.comments.push({id:uid('c'),author:ME,text:value,at:new Date().toISOString()});activity('оставил комментарий к странице',p.id);save();render();toast('Комментарий добавлен');});
  $('#workspace-form',root)?.addEventListener('submit',ev=>{ev.preventDefault();const v=ev.target.workspace.value.trim();if(!v)return;state.workspace=v;save();render();toast('Название пространства сохранено');});
  $('#import-file',root)?.addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;if(file.size>10*1024*1024){toast('Файл слишком большой. Максимум — 10 МБ.');return;}try{const imported=validateState(JSON.parse(await file.text()));if(!confirm('Заменить текущие данные содержимым файла?'))return;for(const key of ['boards','databases','folders','links','projects','reviews'])imported[key]??=[];state=imported;state.favorites=Array.isArray(state.favorites)?state.favorites.filter(id=>typeof id==='string'):[];state.pages.forEach(p=>{p.content=sanitize(p.content);p.versions.forEach(v=>v.content=sanitize(v.content));});save();go('home');render();toast('Данные импортированы');}catch{toast('Не удалось импортировать файл: проверьте формат Apollo Task.');}ev.target.value='';});
}
function action(name,node){if(name==='new-project'){agency.newProject();return;}
  if(ext.action(name,node))return;
  if(name==='mobile-menu'){document.body.classList.toggle('mobile-nav-open');return;}
  if(name==='dismiss-banner'){state.dismissedWelcome=true;save();render();return;}
  if(name==='search'){searchModal();return;}
  if(name==='create'){createMenu();return;}
  if(name==='new-page'){ext.newPage('page','blank',node.dataset.space);return;}
  if(name==='new-space'){spaceModal();return;}
  if(name==='new-task'){taskModal(null,{page:node.dataset.page,status:node.dataset.status});return;}
  if(name==='new-person'&&!cloud.preview){agency.addAccount();return;}if(name==='new-person'){editPersonModal();return;}
  if(name==='profile'){personModal(ME);return;}
  if(name==='edit-page'){editPage(node.dataset.id);if(page(node.dataset.id)?.kind==='live')ext.attachLiveEditor(node.dataset.id);return;}
  if(name==='history'){historyModal(node.dataset.id);return;}
  if(name==='share'){shareModal(node.dataset.id);return;}
  if(name==='help'){helpModal();return;}
  if(name==='notifications'){notificationsModal();return;}
  if(name==='export'){download();return;}
  if(name==='space-tasks'){taskSpace=node.dataset.space;taskScope='all';go('tasks');return;}
  if(name==='reset'){openModal('Восстановить демо-данные',`<p class="modal-description">Текущие страницы, задачи и комментарии будут заменены первоначальным примером. Сохраните экспорт, если хотите вернуться к своей работе.</p><div class="modal-footer"><button class="btn secondary" id="export-before-reset">Экспортировать данные</button><button class="btn danger" id="confirm-reset">Восстановить</button></div>`);$('#export-before-reset').onclick=download;$('#confirm-reset').onclick=()=>{state=seed();save();go('home');render();toast('Демо-пространство восстановлено');};}
}
function openModal(title,body,cls=''){
  closeModal(false);modalReturn=document.activeElement;overlay.innerHTML=`<div class="modal-backdrop"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${e(title)}</h2><button class="icon-btn" id="modal-close" aria-label="Закрыть">${icon('close')}</button></header><div class="modal-body">${body}</div></section></div>`;document.body.classList.add('modal-open');$('#modal-close').onclick=()=>closeModal();$('.modal-backdrop').onclick=ev=>{if(ev.target.classList.contains('modal-backdrop'))closeModal();};requestAnimationFrame(()=>($('.modal input:not([type="hidden"])')||$('.modal textarea')||$('.modal button'))?.focus());
}
function closeModal(restore=true){$('.create-btn')?.setAttribute('aria-expanded','false');overlay.innerHTML='';document.body.classList.remove('modal-open');if(restore&&modalReturn?.isConnected)modalReturn.focus();}
function createMenu(){openModal('Что создаём?',`<div class="create-options"><button data-create-type="page"><span class="space-icon blue">${icon('file')}</span><span><strong>Страница</strong><small>Сохранить знания, идею или договорённость</small></span>${icon('chevron')}</button><button data-create-type="task"><span class="space-icon green">${icon('task')}</span><span><strong>Задача</strong><small>Определить следующий шаг и ответственного</small></span>${icon('chevron')}</button><button data-create-type="space"><span class="space-icon purple">${icon('grid')}</span><span><strong>Пространство</strong><small>Объединить страницы по теме или команде</small></span>${icon('chevron')}</button></div><button class="template-menu-link text-link" id="open-templates">${icon('template')}Или начните с готового шаблона ${icon('arrow')}</button>`,'compact-modal');document.querySelectorAll('[data-create-type]').forEach(n=>n.onclick=()=>{if(n.dataset.createType==='page')newPageModal();if(n.dataset.createType==='task')taskModal();if(n.dataset.createType==='space')spaceModal();});$('#open-templates').onclick=()=>go('templates');}
function newPageModal(templateId='blank',spaceId){const t=templates.find(t=>t.id===templateId)||templates[0];openModal('Новая страница',`<p class="modal-description">${t.id==='blank'?'Сохраните то, что поможет вашей команде.':`Шаблон «${e(t.title)}» поможет начать с готовой структуры.`}</p><form id="new-page-form"><label class="field">Название страницы<input name="title" placeholder="Например, план запуска проекта" required maxlength="150" autocomplete="off"></label><label class="field">Пространство<select name="space">${state.spaces.map(s=>`<option value="${e(s.id)}" ${s.id===spaceId?'selected':''}>${e(s.name)}</option>`).join('')}</select></label><label class="field">Шаблон<select name="template">${ext.allTemplates.filter(t=>!t.kind).map(t=>`<option value="${t.id}" ${t.id===templateId?'selected':''}>${e(t.title)}</option>`).join('')}</select></label><div class="modal-footer"><button class="btn secondary" type="button" id="cancel-new-page">Отмена</button><button class="btn primary" type="submit">Создать страницу ${icon('arrow')}</button></div></form>`);$('#cancel-new-page').onclick=()=>closeModal();$('#new-page-form').onsubmit=ev=>{ev.preventDefault();const f=ev.target,title=f.title.value.trim();if(!title){f.title.focus();return;}const template=templates.find(t=>t.id===f.template.value),p={id:uid('page'),space:f.space.value,title,icon:template.icon,excerpt:template.description,owner:ME,updated:new Date().toISOString(),status:'draft',comments:[],versions:[],content:template.content};state.pages.unshift(p);activity('создал страницу',p.id);save();editing=false;go(`page/${p.id}`);render();editPage(p.id);};}
function spaceModal(){openModal('Новое пространство',`<p class="modal-description">Объедините знания по теме, проекту или направлению.</p><form id="space-form"><label class="field">Название<input name="title" required maxlength="60" placeholder="Например, Клиентский сервис"></label><label class="field">Описание<textarea name="description" rows="3" maxlength="180" placeholder="Что команда найдёт в этом пространстве?"></textarea></label><fieldset class="color-field"><legend>Цвет пространства</legend>${['blue','purple','green','orange'].map((c,i)=>`<label class="color-choice ${c}"><input type="radio" name="color" value="${c}" ${i===0?'checked':''}><span>${icon('check')}</span></label>`).join('')}</fieldset><div class="modal-footer"><button class="btn secondary" type="button" id="cancel-space">Отмена</button><button class="btn primary">Создать пространство</button></div></form>`);$('#cancel-space').onclick=()=>closeModal();$('#space-form').onsubmit=ev=>{ev.preventDefault();const f=ev.target,title=f.title.value.trim();if(!title)return;const s={id:uid('space'),name:title,description:f.description.value.trim(),color:f.color.value,icon:'grid'};state.spaces.push(s);save();go(`space/${s.id}`);render();toast('Пространство создано');};}
function taskModal(id,defaults={}){const t=state.tasks.find(t=>t.id===id);const related=t?.page||defaults.page||'';const selectedSpace=t?.space||page(related)?.space||(taskSpace==='all'?state.spaces[0].id:taskSpace);openModal(t?'Задача':'Новая задача',`<form id="task-form"><label class="field">Что нужно сделать<input name="title" value="${e(t?.title||'')}" placeholder="Сформулируйте конкретный результат" maxlength="180" required></label><label class="field">Описание<textarea name="description" rows="3" placeholder="Контекст, детали и ожидаемый результат" maxlength="3000">${e(t?.description||'')}</textarea></label><div class="form-grid"><label class="field">Ответственный<select name="assignee">${state.people.map(p=>`<option value="${e(p.id)}" ${(t?.assignee||ME)===p.id?'selected':''}>${e(p.name)}</option>`).join('')}</select></label><label class="field">Срок<input type="date" name="due" value="${e(t?.due||'')}"></label><label class="field">Статус<select name="status">${Object.entries(statuses).map(([key,label])=>`<option value="${key}" ${(t?.status||defaults.status||'todo')===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Приоритет<select name="priority"><option value="low" ${t?.priority==='low'?'selected':''}>Низкий</option><option value="normal" ${!t||t.priority==='normal'?'selected':''}>Обычный</option><option value="high" ${t?.priority==='high'?'selected':''}>Высокий</option></select></label></div><label class="field">Клиентский проект<select name="project" id="task-modal-project"><option value="">Без проекта</option>${state.projects.filter(p=>!p.archived||p.id===t?.project).map(p=>`<option value="${e(p.id)}" ${p.id===(t?.project||defaults.project||page(related)?.project)?'selected':''}>${e(p.title)}</option>`).join('')}</select></label><label class="field">Пространство<select name="space" id="task-modal-space">${state.spaces.map(s=>`<option value="${e(s.id)}" ${selectedSpace===s.id?'selected':''}>${e(s.name)}</option>`).join('')}</select></label><label class="field">Связанная страница<select name="page" id="task-modal-page">${pageOptions(selectedSpace,related)}</select></label><div class="modal-footer spread">${t?`<button class="btn ghost danger-text" type="button" id="delete-task">${icon('trash')}Удалить</button>`:'<span></span>'}<div class="button-row"><button class="btn secondary" type="button" id="cancel-task">Отмена</button><button class="btn primary">${t?'Сохранить':'Создать задачу'}</button></div></div></form>`);$('#cancel-task').onclick=()=>closeModal();$('#task-modal-space').onchange=ev=>{$('#task-modal-page').innerHTML=pageOptions(ev.target.value,'');$('#task-modal-project').value='';};$('#task-modal-project').onchange=ev=>{const pr=state.projects.find(p=>p.id===ev.target.value);if(pr){$('#task-modal-space').value=pr.space;$('#task-modal-page').innerHTML=pageOptions(pr.space,pr.brief);}};$('#task-form').onsubmit=ev=>{ev.preventDefault();const f=ev.target,title=f.title.value.trim();if(!title)return;const values={title,description:f.description.value.trim(),assignee:f.assignee.value,due:f.due.value,status:f.status.value,priority:f.priority.value,space:f.space.value,page:f.page.value||null,project:f.project.value||null};if(values.project){const pr=state.projects.find(p=>p.id===values.project);values.space=pr.space;if(values.page&&page(values.page)?.space!==pr.space)values.page=null;}if(t)Object.assign(t,values);else state.tasks.push({id:uid('task'),...values});activity(t?'обновил задачу':'создал задачу',values.page);save();closeModal();render();toast(t?'Задача сохранена':'Задача создана');};$('#delete-task')?.addEventListener('click',()=>{if(!confirm('Удалить эту задачу?'))return;state.tasks=state.tasks.filter(x=>x.id!==id);save();closeModal();render();toast('Задача удалена');});}
function pageOptions(spaceId,selected){return `<option value="">Без связанной страницы</option>${state.pages.filter(p=>p.space===spaceId).map(p=>`<option value="${e(p.id)}" ${p.id===selected?'selected':''}>${e(p.title)}</option>`).join('')}`;}
function personModal(id){const p=people(id),tasks=state.tasks.filter(t=>t.assignee===p.id&&t.status!=='done');openModal(p.name,`<div class="person-profile">${avatar(id,'xl')}<h3>${e(p.role)}</h3>${pill(p.team,p.color)}</div><div class="profile-section"><h3>Зона ответственности</h3><p>${e(p.responsibility)}</p></div><div class="profile-section"><h3>Рабочий контакт</h3><p class="person-inline">${icon('mail')}${e(p.email||'Не указан')}</p></div><div class="profile-section"><h3>Активные задачи <span class="count-light">${tasks.length}</span></h3>${tasks.map(t=>`<button class="profile-task" data-profile-task="${e(t.id)}">${icon('task')}<span>${e(t.title)}</span>${pill(statuses[t.status],t.status==='progress'?'blue':'neutral')}</button>`).join('')||'<p class="subtle">Активных задач пока нет.</p>'}</div><div class="modal-footer"><button class="btn secondary" id="edit-person">${icon('edit')}Редактировать карточку</button></div>`);$('#edit-person').onclick=()=>editPersonModal(id);document.querySelectorAll('[data-profile-task]').forEach(n=>n.onclick=()=>taskModal(n.dataset.profileTask));}
function editPersonModal(id){const p=id?people(id):null;openModal(p?'Редактировать сотрудника':'Добавить сотрудника',`<p class="modal-description">Опишите роль сотрудника. Для предоставления доступа к сервису используйте приглашения в настройках.</p><form id="person-form"><label class="field">Имя и фамилия<input name="name" value="${e(p?.name||'')}" required maxlength="80" placeholder="Имя Фамилия"></label><div class="form-grid"><label class="field">Должность<input name="role" value="${e(p?.role||'')}" required maxlength="100" placeholder="Например, Дизайнер"></label><label class="field">Команда<input name="team" value="${e(p?.team||'')}" required maxlength="60" placeholder="Например, Продукт"></label></div><label class="field">Рабочая почта<input name="email" type="email" value="${e(p?.email||'')}" maxlength="120" placeholder="name@company.ru"></label><label class="field">Зона ответственности<textarea name="responsibility" required rows="4" maxlength="600" placeholder="За что отвечает и какие решения принимает">${e(p?.responsibility||'')}</textarea></label><div class="modal-footer"><button class="btn secondary" type="button" id="cancel-person">Отмена</button><button class="btn primary">${p?'Сохранить':'Добавить сотрудника'}</button></div></form>`);$('#cancel-person').onclick=()=>closeModal();$('#person-form').onsubmit=ev=>{ev.preventDefault();const f=ev.target;const values={name:f.elements.namedItem('name').value.trim(),role:f.role.value.trim(),team:f.team.value.trim(),email:f.email.value.trim(),responsibility:f.responsibility.value.trim()};if(!values.name||!values.role||!values.team||!values.responsibility)return;if(p)Object.assign(p,values);else state.people.push({id:uid('person'),color:['blue','purple','green','orange','pink'][state.people.length%5],...values});save();closeModal();render();toast(p?'Карточка сохранена':'Карточка сотрудника добавлена');};}
function editPage(id){const p=page(id);if(!p)return;editing=true;const main=$('.page-content');main.innerHTML=`<div class="editor-top"><div class="breadcrumb"><span>${e(space(p.space).name)}</span>${icon('chevron')}<span>Редактирование</span></div><div class="button-row"><span class="editor-save-hint">Изменения ещё не сохранены</span><button class="btn secondary" id="cancel-editor">Отмена</button><button class="btn primary" id="save-editor">${icon('check')}Сохранить</button></div></div><div class="editor-layout"><div class="editor-paper"><label class="sr-only" for="edit-title">Название страницы</label><input id="edit-title" class="edit-title" value="${e(p.title)}" maxlength="150" placeholder="Название страницы"><div class="editor-toolbar" role="toolbar" aria-label="Форматирование текста"><button type="button" data-format="formatBlock" data-value="p" title="Обычный текст">Текст</button><button type="button" data-format="formatBlock" data-value="h2" title="Заголовок">H2</button><span></span><button type="button" data-format="bold" title="Жирный"><b>Ж</b></button><button type="button" data-format="italic" title="Курсив"><i>К</i></button><button type="button" data-format="insertUnorderedList" title="Маркированный список">${icon('list')}</button><button type="button" data-format="insertOrderedList" title="Нумерованный список">1.</button><button type="button" data-format="formatBlock" data-value="blockquote" title="Цитата">“ ”</button><span></span><button type="button" id="editor-link" title="Добавить ссылку">${icon('link')}</button><button type="button" data-format="removeFormat" title="Убрать форматирование">Т̲×</button></div><div id="page-editor" class="document-body page-editor" contenteditable="true" role="textbox" aria-label="Содержимое страницы" aria-multiline="true">${sanitize(p.content)}</div></div><aside class="editor-settings"><h3>Настройки страницы</h3><label class="field">Ответственный<select id="edit-owner">${state.people.map(x=>`<option value="${e(x.id)}" ${x.id===p.owner?'selected':''}>${e(x.name)}</option>`).join('')}</select></label><label class="field">Статус<select id="edit-status"><option value="published" ${p.status==='published'?'selected':''}>Актуально</option><option value="draft" ${p.status==='draft'?'selected':''}>Черновик</option><option value="review" ${p.status==='review'?'selected':''}>Нужна проверка</option></select></label><label class="field">Краткое описание<textarea id="edit-excerpt" rows="4" maxlength="200">${e(p.excerpt)}</textarea></label><div class="editor-tip">${icon('info')}<p>У страницы есть владелец, который отвечает за актуальность. Каждое сохранение создаёт версию в истории.</p></div><button class="btn ghost danger-text" id="delete-page">${icon('trash')}Удалить страницу</button></aside></div>`;
  $('#cancel-editor').onclick=()=>{if(confirm('Отменить изменения?')){editing=false;render();}};
  $('#save-editor').onclick=()=>{const title=$('#edit-title').value.trim();if(!title){toast('Добавьте название страницы');$('#edit-title').focus();return;}p.versions.unshift({title:p.title,content:p.content,at:p.updated,owner:p.owner});p.versions=p.versions.slice(0,30);p.title=title;p.content=sanitize($('#page-editor').innerHTML);p.owner=$('#edit-owner').value;p.status=$('#edit-status').value;p.excerpt=$('#edit-excerpt').value.trim();p.updated=new Date().toISOString();activity('обновил страницу',p.id);save();editing=false;render();toast('Страница сохранена');};
  document.querySelectorAll('[data-format]').forEach(n=>{n.onmousedown=ev=>ev.preventDefault();n.onclick=()=>{$('#page-editor').focus();document.execCommand(n.dataset.format,false,n.dataset.value||null);};});
  $('#editor-link').onmousedown=ev=>ev.preventDefault();$('#editor-link').onclick=()=>{const href=prompt('Адрес ссылки (https://…)');if(href&&/^https?:\/\//i.test(href)){document.execCommand('createLink',false,href);}else if(href)toast('Укажите ссылку, начинающуюся с https:// или http://');};
  $('#page-editor').onpaste=ev=>{ev.preventDefault();const text=ev.clipboardData.getData('text/plain');document.execCommand('insertText',false,text);};
  $('#delete-page').onclick=()=>{if(!confirm('Удалить страницу? Связанные задачи сохранятся без ссылки на неё.'))return;if(state.projects.some(x=>x.brief===p.id)){toast('Бриф связан с проектом. Сохраните его или уберите проект в архив.');return;}state.reviews=state.reviews.filter(x=>x.page!==p.id);state.pages=state.pages.filter(x=>x.id!==p.id);state.favorites=(state.favorites||[]).filter(x=>x!==p.id);state.tasks=state.tasks.map(t=>t.page===p.id?{...t,page:null}:t);state.activity=state.activity.map(a=>a.page===p.id?{...a,page:null}:a);save();editing=false;go('knowledge');render();toast('Страница удалена');};
  $('#edit-title').focus();
}
function historyModal(id){const p=page(id);openModal('История страницы',`<p class="modal-description">${e(p.title)}. Текущая версия сохранена ${dateLabel(p.updated)}.</p>${p.versions.length?`<div class="version-list">${p.versions.map((v,i)=>`<div class="version-row"><span class="version-icon">${icon('history')}</span><div><strong>${e(v.title)}</strong><small>${dateLabel(v.at)} · ${new Date(v.at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</small></div><button class="btn secondary" data-version="${i}">Посмотреть</button></div>`).join('')}</div>`:empty('Пока одна версия','Предыдущие версии появятся после первого редактирования.')}`,'wide-modal');document.querySelectorAll('[data-version]').forEach(n=>n.onclick=()=>{const idx=+n.dataset.version,v=p.versions[idx];openModal('Предыдущая версия',`<p class="modal-description">${dateLabel(v.at)} · ${e(v.title)}</p><div class="document-body version-preview">${sanitize(v.content)}</div><div class="modal-footer"><button class="btn secondary" id="back-history">Назад</button><button class="btn primary" id="restore-version">Восстановить версию</button></div>`,'wide-modal');$('#back-history').onclick=()=>historyModal(id);$('#restore-version').onclick=()=>{const restored={...v};p.versions.unshift({title:p.title,content:p.content,at:p.updated,owner:p.owner});p.versions=p.versions.slice(0,30);p.title=restored.title;p.content=sanitize(restored.content);p.updated=new Date().toISOString();activity('восстановил версию страницы',p.id);save();closeModal();render();toast('Версия восстановлена');};});}
function shareModal(id){const url=new URL(location.href);url.hash=`page/${id}`;openModal('Ссылка на страницу',`<p class="modal-description">Ссылка открывает страницу в текущем пространстве. Пользовательские данные пока хранятся только в вашем браузере: для переноса используйте экспорт в настройках.</p><label class="field">Адрес страницы<input id="share-url" readonly value="${e(url.href)}"></label><div class="modal-footer"><button class="btn primary" id="copy-link">${icon('link')}Скопировать ссылку</button></div>`);$('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(url.href);toast('Ссылка скопирована');closeModal();}catch{$('#share-url').select();toast('Выделили ссылку — скопируйте её вручную.');}};}
function searchModal(){searchIndex=-1;openModal('Поиск по пространству',`<div class="search-modal-input">${icon('search')}<input id="search-input" placeholder="Страницы, задачи, сотрудники…" autocomplete="off" aria-label="Поиск по пространству"><kbd>Esc</kbd></div><div id="search-results"><div class="search-initial"><span class="eyebrow">НЕДАВНИЕ СТРАНИЦЫ</span>${filteredPages('recent').slice(0,4).map(p=>searchResult({kind:'page',id:p.id,title:p.title,subtitle:space(p.space).name,icon:p.icon})).join('')}</div></div><div class="search-shortcuts"><span><kbd>↑</kbd><kbd>↓</kbd> выбрать</span><span><kbd>Enter</kbd> открыть</span></div>`,'search-modal');bindSearchResults();const input=$('#search-input');input.focus();input.oninput=()=>{searchIndex=-1;const results=[...searchRecords(state,input.value),...ext.search(input.value)];$('#search-results').innerHTML=input.value.trim()?(results.length?`<p class="search-count">Найдено: ${results.length}</p>${results.slice(0,20).map(searchResult).join('')}`:empty('Ничего не нашли','Попробуйте другое слово или часть названия.')):`<div class="search-initial"><span class="eyebrow">НЕДАВНИЕ СТРАНИЦЫ</span>${filteredPages('recent').slice(0,4).map(p=>searchResult({kind:'page',id:p.id,title:p.title,subtitle:space(p.space).name,icon:p.icon})).join('')}</div>`;bindSearchResults();};input.onkeydown=ev=>{const results=[...document.querySelectorAll('[data-search-kind]')];if(ev.key==='ArrowDown'||ev.key==='ArrowUp'){ev.preventDefault();searchIndex=Math.max(0,Math.min(results.length-1,searchIndex+(ev.key==='ArrowDown'?1:-1)));results.forEach((n,i)=>n.classList.toggle('selected',i===searchIndex));results[searchIndex]?.scrollIntoView({block:'nearest'});}if(ev.key==='Enter'){ev.preventDefault();results[Math.max(0,searchIndex)]?.click();}};}
function searchResult(r){return `<button class="search-result" data-search-kind="${r.kind}" data-search-id="${e(r.id)}"><span class="page-type-icon blue">${icon(r.icon)}</span><span><strong>${e(r.title)}</strong><small>${e(r.subtitle)}</small></span>${icon('arrow')}</button>`;}
function bindSearchResults(){document.querySelectorAll('[data-search-kind]').forEach(n=>n.onclick=()=>{const id=n.dataset.searchId,kind=n.dataset.searchKind;if(kind==='page')go(`page/${id}`);if(kind==='task')taskModal(id);if(kind==='person')personModal(id);if(['board','database','folder','link','live'].includes(kind))go(kind==='live'?`page/${id}`:`${kind}/${id}`);});}
function notificationsModal(){state.notificationsRead=true;save();$('.notification-btn')?.classList.remove('has-dot');openModal('Уведомления',`<p class="modal-description">Последние изменения в рабочем пространстве.</p>${state.activity.slice(0,12).map(a=>`<div class="notification-row">${avatar(a.person,'small')}<div><p><strong>${e(people(a.person).name)}</strong> ${e(a.text)}</p>${a.page&&page(a.page)?`<button class="text-link" data-notification-page="${e(a.page)}">${e(page(a.page).title)}</button>`:''}<small>${ago(a.at)}</small></div></div>`).join('')}`);document.querySelectorAll('[data-notification-page]').forEach(n=>n.onclick=()=>go(`page/${n.dataset.notificationPage}`));}
function helpModal(){openModal('Добро пожаловать в Apollo Task',`<div class="help-intro"><img src="./apollo-symbol.svg" width="46" height="46" alt=""><p>Меньше поисков. Больше ясности.<br><strong>Рабочее пространство компании.</strong></p></div><div class="help-step"><span>1</span><div><h3>Соберите знания</h3><p>Создавайте страницы с нуля или по шаблону и объединяйте их в пространства.</p></div></div><div class="help-step"><span>2</span><div><h3>Сделайте ответственность понятной</h3><p>Заполните карточки сотрудников и назначьте владельцев страниц.</p></div></div><div class="help-step"><span>3</span><div><h3>Договоритесь о следующем шаге</h3><p>Создайте задачу, выберите исполнителя, срок и связанную страницу.</p></div></div><div class="info-callout">${icon('info')}<p>Apollo Task сохраняет данные на сервере. Вход — по логину и паролю, которые выдаёт Apollo или администратор компании. Аккаунты связаны с рабочими пространствами, доступ проверяется на сервере. Данные автоматически обновляются каждые 5 секунд. В демо используются вымышленные клиенты. Новое пространство создаётся с вашей карточкой и инструкцией для команды.</p></div><p class="help-shortcut"><kbd>Ctrl / ⌘ K</kbd> — поиск по всему пространству</p><div class="modal-footer"><button class="btn primary" id="help-start">Всё понятно ${icon('arrow')}</button></div>`);$('#help-start').onclick=()=>closeModal();}
function download(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`apollo-task-${localDay()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Экспорт подготовлен');}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'home';if(editing){if(!confirm('Выйти без сохранения изменений?')){history.replaceState(null,'',`#${route}`);return;}editing=false;}route=next;render();window.scrollTo(0,0);});
window.addEventListener('beforeunload',ev=>{if(editing||cloud.pending||cloud.busy){ev.preventDefault();ev.returnValue='';}});
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();searchModal();}if(ev.key==='Escape'){if(overlay.firstChild)closeModal();document.body.classList.remove('mobile-nav-open');}if(ev.key==='Tab'&&overlay.firstChild){const elements=[...overlay.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=elements[0],last=elements.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}});
const ext=createExtension({getState:()=>state,getRoute:()=>route,getUser:()=>cloud.user,getMembers:()=>cloud.members,getWorkspaces:()=>cloud.workspaces,getWorkspaceId:()=>cloud.workspaceId,isPreview:()=>cloud.preview,syncLabel,heading,empty,avatar,pill,taskListRow,openModal,closeModal,toast,go,render,save,sanitize,api,switchWorkspace,refresh:()=>refreshCloud(true),newPageModal,taskModal,spaceModal,editPersonModal,importLegacy});
const agency=createAgency({app,getState:()=>state,getRoute:()=>route,getMembers:()=>cloud.members,getUser:()=>cloud.user,getWorkspaceId:()=>cloud.workspaceId,refresh:()=>refreshCloud(true),isViewer:()=>cloud.user.role==='viewer',navItem,heading,empty,avatar,taskListRow,openModal,closeModal,toast,go,render,save,api,boot,taskModal,newProjectPage(p){ext.newPage('page','agency-client-brief',p.space);const f=$('#new-page-form');if(f?.parent)f.parent.value=p.folder;const old=f.onsubmit;f.onsubmit=ev=>{const ids=new Set(state.pages.map(x=>x.id));old(ev);const added=state.pages.find(x=>!ids.has(x.id));if(added){added.project=p.id;added.parent=p.folder;save();}};},demo(data){state=data;setCurrentUser('roman');cloud={...cloud,preview:true,workspaceId:null,members:[],user:{id:'roman',name:'Алексей Морозов',role:'demo'},ready:true};route='home';}});
document.addEventListener('apollo-new-project',()=>agency.newProject());
agency.start();
setInterval(()=>refreshCloud(),5000);
